import sqlite3, yaml, re, collections, itertools
c=sqlite3.connect('file:data/guidebook.db?mode=ro',uri=True)
st=yaml.safe_load(open('governance/stage-map.yaml'))['tables']; spine=[s['id'] for s in yaml.safe_load(open('governance/pipeline-contract.yaml'))['stages']]
T=[r[0] for r in c.execute("select name from sqlite_master where type='table' and name not like 'sqlite_%'")]; V=dict(c.execute("select name, sql from sqlite_master where type='view'").fetchall())
stage={t:st.get(t,'UNMAPPED') for t in T}
fk=[(t,f[2],f[3]) for t in T for f in c.execute(f'pragma foreign_key_list("{t}")') if f[2] in stage]
vedge={v:sorted({t for t in T if re.search(rf'\b{re.escape(t)}\b',s)}) for v,s in V.items()}
live_fk={(ch,pa) for ch,pa,cc in fk if c.execute(f'select 1 from "{ch}" where "{cc}" is not null limit 1').fetchone()}
live_v={v for v in vedge if c.execute(f'select 1 from "{v}" limit 1').fetchone()}
und=collections.defaultdict(set)
for ch,pa in live_fk: und[ch].add(pa); und[pa].add(ch)
for v in live_v:
    for x in vedge[v]:
        for y in vedge[v]:
            if x!=y: und[x].add(y)
isfk=lambda x,y:(x,y) in live_fk or (y,x) in live_fk
by=collections.defaultdict(list)
for t in T: by[stage[t]].append(t)
# exact: enumerate all shortest paths (by length) from every src, pick min (len, viewhops, path)
def best(A,B):
    B=set(B); res=None
    for s0 in A:
        dist={s0:0}; q=collections.deque([s0]); layers={}
        while q:
            n=q.popleft()
            if n in B: continue
            if stage[n]=='base' and n!=s0: continue
            for m in und[n]:
                if m not in dist: dist[m]=dist[n]+1; q.append(m)
        tgt=[b for b in B if b in dist]
        if not tgt: continue
        L=min(dist[b] for b in tgt)
        # enumerate all paths of length L via DFS on dist layers
        def paths(n,acc):
            if n in B and dist[n]==L: yield acc+[n]; return
            if n in B: return
            if stage[n]=='base' and n!=s0: return
            for m in und[n]:
                if dist.get(m)==dist[n]+1: yield from paths(m,acc+[n])
        for p in paths(s0,[]):
            cost=(len(p),sum(not isfk(x,y) for x,y in zip(p,p[1:])),p)
            if res is None or cost<res: res=cost
    return res
for a,b in itertools.combinations([s for s in spine if s!='base'],2):
    r=best(by[a],by[b])
    if r: print(f'{a}<->{b}: len {r[0]} viewhops {r[1]} :', ' - '.join(r[2]))
